css:
[data-theme="rainbow-dark"] .section:nth-of-type(4n+1) .category-icon,
[data-theme="rainbow-dark"] .section:nth-of-type(4n+1) .category-name { color: #ff8fab; }
[data-theme="rainbow-dark"] .section:nth-of-type(4n+2) .category-icon,
[data-theme="rainbow-dark"] .section:nth-of-type(4n+2) .category-name { color: #ffd166; }
[data-theme="rainbow-dark"] .section:nth-of-type(4n+3) .category-icon,
[data-theme="rainbow-dark"] .section:nth-of-type(4n+3) .category-name { color: #80ed99; }
[data-theme="rainbow-dark"] .section:nth-of-type(4n+4) .category-icon,
[data-theme="rainbow-dark"] .section:nth-of-type(4n+4) .category-name { color: #8ec5ff; }

[data-theme="rainbow-dark"] .web-link:nth-child(5n+1) .web-link-icon { color: #ff8fab; }
[data-theme="rainbow-dark"] .web-link:nth-child(5n+2) .web-link-icon { color: #ffd166; }
[data-theme="rainbow-dark"] .web-link:nth-child(5n+3) .web-link-icon { color: #80ed99; }
[data-theme="rainbow-dark"] .web-link:nth-child(5n+4) .web-link-icon { color: #8ec5ff; }
[data-theme="rainbow-dark"] .web-link:nth-child(5n+5) .web-link-icon { color: #c8a2ff; }
